@router.get("/api/v1/llm/sessions/{session_id}/token-stream")
async def stream_llm_generation(
    session_id: str,
    ai_gateway: LLMGateway = Depends(get_llm_gateway),
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    session_stmt = select(LLMSessionRecord).where(
        LLMSessionRecord.id == session_id,
        LLMSessionRecord.user_id == current_user.id
    )
    res = await db.execute(session_stmt)
    rec = res.scalar_one_or_none()
    if not rec:
        raise HTTPException(status_code=404, detail="LLM session not found or unauthorized")

    async def token_generator():
        async for token_chunk in ai_gateway.stream_tokens(session_id):
            yield {"event": "token", "data": token_chunk}

    return EventSourceResponse(token_generator())
